package com.aurum.scalp;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;
import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;

/** Controlled fixtures live only in the test APK. Exercises the real native Activity and bundled renderer. */
final class ChartChecks {
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 private static void await(BooleanSupplier p,String message)throws Exception{long end=SystemClock.elapsedRealtime()+60000;while(!p.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(p.getAsBoolean(),message);}
 private static View find(View v,String description){if(description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View r=find(g.getChildAt(n),description);if(r!=null)return r;}}return null;}
 private static void click(Instrumentation i,Activity a,String description){i.runOnMainSync(()->{View v=find(a.getWindow().getDecorView(),description);check(v!=null,"Control exists: "+description);v.performClick();});}
 private static void layer(Instrumentation i,ChartActivity a,int index)throws Exception{
  click(i,a,"Chart layers");i.waitForIdleSync();java.lang.reflect.Field menu=ChartActivity.class.getDeclaredField("layerMenu");menu.setAccessible(true);AlertDialog dialog=(AlertDialog)menu.get(a);
  i.runOnMainSync(()->{ListView list=dialog.getListView();list.performItemClick(list.getChildAt(index),index,list.getItemIdAtPosition(index));dialog.dismiss();});
 }
 private static String js(Instrumentation i,WebView w,String script)throws Exception{AtomicReference<String> result=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);i.runOnMainSync(()->w.evaluateJavascript(script,value->{result.set(value);done.countDown();}));check(done.await(15,TimeUnit.SECONDS),"WebView evaluation returns");return result.get();}
 private static JSONObject state(Instrumentation i,WebView w)throws Exception{return new JSONObject(js(i,w,"window.AurumChart&&window.__aurumReady?window.AurumChart.inspect():{}"));}
 private static boolean ready(Instrumentation i,WebView w,String frame,int count){try{JSONObject s=state(i,w);return frame.equals(s.optString("frame"))&&s.optInt("closedCount")==count;}catch(Exception e){return false;}}
 private static void touch(Instrumentation i,long down,int action,float x,float y){android.view.MotionEvent e=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),action,x,y,0);i.sendPointerSync(e);e.recycle();}
 private static void pair(Instrumentation i,long down,int action,float x,float y,float gap){android.view.MotionEvent.PointerProperties[] ids=new android.view.MotionEvent.PointerProperties[2];android.view.MotionEvent.PointerCoords[] coords=new android.view.MotionEvent.PointerCoords[2];for(int n=0;n<2;n++){ids[n]=new android.view.MotionEvent.PointerProperties();ids[n].id=n;ids[n].toolType=android.view.MotionEvent.TOOL_TYPE_FINGER;coords[n]=new android.view.MotionEvent.PointerCoords();coords[n].x=x+(n==0?-gap:gap);coords[n].y=y;coords[n].pressure=1;coords[n].size=1;}android.view.MotionEvent e=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),action,2,ids,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);i.sendPointerSync(e);e.recycle();}
 private static int gestures(Instrumentation i,AdvancedChartView web)throws Exception{
  JSONObject b=new JSONObject(js(i,web,"(()=>{const r=document.getElementById('plot').getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height,viewport:innerWidth};})()"));int[] position=new int[3];i.runOnMainSync(()->{web.getLocationOnScreen(position);position[2]=web.getWidth();});float scale=(float)(position[2]/b.getDouble("viewport"));float x=position[0]+(float)(b.getDouble("x")+b.getDouble("w")*.42)*scale,y=position[1]+(float)(b.getDouble("y")+b.getDouble("h")*.48)*scale;
  long down=SystemClock.uptimeMillis();touch(i,down,0,x,y);try{await(()->{try{return state(i,web).optLong("selected")>0;}catch(Exception e){return false;}},"Actual Android long press selects candle");}finally{touch(i,down,1,x,y);}
  JSONObject before=state(i,web).getJSONObject("range");float gap=(float)b.getDouble("w")*scale*.10f;down=SystemClock.uptimeMillis();touch(i,down,0,x-gap,y);pair(i,down,android.view.MotionEvent.ACTION_POINTER_DOWN|(1<<8),x,y,gap);for(int n=1;n<=10;n++){pair(i,down,2,x,y,gap*(1+n*.12f));Thread.sleep(100);}pair(i,down,android.view.MotionEvent.ACTION_POINTER_UP|(1<<8),x,y,gap*2.2f);touch(i,down,1,x-gap*2.2f,y);await(()->{try{JSONObject after=state(i,web).getJSONObject("range");return Math.abs((before.getDouble("to")-before.getDouble("from"))-(after.getDouble("to")-after.getDouble("from")))>2;}catch(Exception e){return false;}},"Actual Android two-pointer pinch changes zoom");return 2;
 }
 static int run(Instrumentation i)throws Exception{
  Context c=i.getTargetContext();AtomicReference<MonitorRuntime> rt=new AtomicReference<>();AtomicReference<MarketRepository> old=new AtomicReference<>();AtomicReference<ChartActivity> activity=new AtomicReference<>();int checks=0;
  File dir=new File(c.getCacheDir(),"chart-check-"+System.nanoTime());check(dir.mkdirs(),"Isolated chart cache");Context isolated=new ContextWrapper(c){@Override public File getFilesDir(){return dir;}};
  MarketRepository repo=new MarketRepository(isolated,()->{if(rt.get()!=null)rt.get().refreshState();},url->{long now=System.currentTimeMillis();if(url.endsWith("/api/XAUUSD"))return new JSONObject().put("symbol","XAUUSD").put("timestamp",java.time.Instant.ofEpochMilli(now-100).toString()).put("bid",4000).put("ask",4000.5).toString();
   Market.Frame f=null;for(Market.Frame candidate:Market.Frame.values())if(url.contains("interval="+BiquoteCodec.interval(candidate)+"&"))f=candidate;if(f==null)throw new IOException("Unknown fixture route");long bucket=now/f.duration()*f.duration();JSONArray bars=new JSONArray();for(int n=260;n>=0;n--){double o=4000+Math.sin(n/8.0)*6;bars.put(new JSONObject().put("openTime",java.time.Instant.ofEpochMilli(bucket-n*f.duration()).toString()).put("open",o).put("high",o+2).put("low",o-2).put("close",o+.5).put("isOpen",n==0));}return new JSONObject().put("symbol","XAUUSD").put("interval",BiquoteCodec.interval(f)).put("bars",bars).toString();});
  java.lang.reflect.Field clock=MarketRepository.class.getDeclaredField("marketClock");clock.setAccessible(true);((MarketClock)clock.get(repo)).sync(System.currentTimeMillis(),SystemClock.elapsedRealtime());
  try{
   i.runOnMainSync(()->{MonitorRuntime r=MonitorRuntime.get(c);rt.set(r);old.set(r.repository);r.repository.stop();r.repository=repo;c.getSharedPreferences("advanced-chart",0).edit().clear().putString("frame","H1").commit();});
   activity.set((ChartActivity)i.startActivitySync(new Intent(c,ChartActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("default-frame","M5")));ChartActivity a=activity.get();java.lang.reflect.Field field=ChartActivity.class.getDeclaredField("chart");field.setAccessible(true);AdvancedChartView web=(AdvancedChartView)field.get(a);
   await(()->ready(i,web,"M5",260),"Market shortcut overrides the saved timeframe and loads native history");checks++;
   check(rt.get().repository==repo&&repo.running(),"Dedicated chart shares the one runtime repository");checks++;
   i.runOnMainSync(()->check(web.getSettings().getTextZoom()==100&&!web.getSettings().getAllowFileAccess()&&!web.getSettings().getAllowContentAccess()&&!web.getSettings().getDomStorageEnabled()&&web.getSettings().getMixedContentMode()==WebSettings.MIXED_CONTENT_NEVER_ALLOW,"WebView local asset and TLS restrictions"));checks++;
   JSONObject s=state(i,web);check(s.getJSONArray("bars").length()>=260&&s.getJSONArray("bars").length()<=262,"Closed history plus display-only preview");check(repo.analyses.get(Market.Frame.M5).candles.size()==260,"Preview stays outside the S/R engine");checks++;
   checks+=gestures(i,web);
   layer(i,a,2);await(()->{try{return state(i,web).optInt("ema200")==61;}catch(Exception e){return false;}},"Native EMA toggle reaches renderer");checks++;
   layer(i,a,0);layer(i,a,1);await(()->{try{return state(i,web).getJSONArray("bands").length()==0;}catch(Exception e){return false;}},"Native zone/context toggles remove overlays");checks++;
   layer(i,a,3);await(()->{try{return state(i,web).getJSONArray("bars").length()==260;}catch(Exception e){return false;}},"Live toggle hides previews but retains closed history");checks++;
   layer(i,a,5);await(()->{try{return js(i,web,"document.getElementById('status').textContent").contains("Sessions ·");}catch(Exception e){return false;}},"Native Session levels toggle reaches renderer");checks++;
   click(i,a,"Focus price on recent candles");await(()->{try{JSONObject x=state(i,web);JSONObject r=x.getJSONObject("range");return x.optBoolean("focusMode")&&r.getDouble("to")-r.getDouble("from")<60;}catch(Exception e){return false;}},"Focus zooms to recent candles");checks++;
   click(i,a,"Return chart to latest and reset scale");await(()->{try{return !state(i,web).optBoolean("focusMode");}catch(Exception e){return false;}},"Latest clears focus mode");checks++;
   click(i,a,"Chart timeframe 4H");await(()->ready(i,web,"H4",260),"Timeframe switch loads H4 independently");check(c.getSharedPreferences("advanced-chart",0).getString("frame","").equals("H4"),"Selected frame saved");checks++;
   click(i,a,"Enter fullscreen chart");i.runOnMainSync(()->{check(find(a.getWindow().getDecorView(),"Exit fullscreen chart").getVisibility()==View.VISIBLE,"Fullscreen exposes exit control");a.onBackPressed();check(find(a.getWindow().getDecorView(),"Enter fullscreen chart").getVisibility()==View.VISIBLE&&!a.isFinishing(),"Back exits fullscreen before leaving Activity");});checks++;
   // Stop fixture transport, then publish a genuine historical correction through the native model.
   i.runOnMainSync(()->{repo.stop();List<Market.Candle> bars=new ArrayList<>(repo.analyses.get(Market.Frame.H4).candles);Market.Candle b=bars.get(90);bars.set(90,new Market.Candle(b.time,b.open,b.high+9,b.low,b.close,b.endTime));Map<Market.Frame,ZoneEngine.Analysis> map=new EnumMap<>(Market.Frame.class);map.putAll(repo.analyses);map.put(Market.Frame.H4,ZoneEngine.calculate(bars,Market.Frame.H4,repo.marketNow()));repo.analyses=map;rt.get().refreshState();});
   double expected=repo.analyses.get(Market.Frame.H4).candles.get(90).high;await(()->{try{return state(i,web).getJSONArray("bars").getJSONObject(90).getDouble("high")==expected;}catch(Exception e){return false;}},"Native history correction updates drawn candle");checks++;
   check(js(i,web,"document.getElementById('legend').textContent").contains("UTC"),"Candle legend exposes UTC and OHLC");checks++;
   i.runOnMainSync(()->{try{web.evaluateJavascript("delete window.AurumChart",null);java.lang.reflect.Method probe=AdvancedChartView.class.getDeclaredMethod("probeRenderer");probe.setAccessible(true);probe.invoke(web);}catch(Exception e){throw new AssertionError(e);}});
   await(()->{try{return js(i,web,"document.getElementById('empty').textContent").contains("Update Android System WebView");}catch(Exception e){return false;}},"Renderer initialisation failure has an actionable fallback");checks++;
   if(Build.VERSION.SDK_INT>=29){i.runOnMainSync(()->{android.webkit.WebViewRenderProcess process=web.getWebViewRenderProcess();check(process!=null&&process.terminate(),"Owned renderer can be terminated for failure test");});await(()->{AtomicBoolean done=new AtomicBoolean();i.runOnMainSync(()->done.set(a.isFinishing()));return done.get();},"Renderer loss returns to native UI without crashing the app");checks++;}else i.runOnMainSync(()->a.finish());
   await(()->!repo.running(),"Leaving last chart viewer stops foreground-only feed");checks++;
  }finally{i.runOnMainSync(()->{if(activity.get()!=null&&!activity.get().isFinishing())activity.get().finish();repo.stop();if(rt.get()!=null){rt.get().repository=old.get();rt.get().refreshState();}c.getSharedPreferences("advanced-chart",0).edit().clear().commit();});}
  return checks;
 }
}
